/** Shared helpers that keep asset and theme paths in one place. */

/** a file in public/, correct under any deploy base (`/` or `/repo-name/`) */
export const asset = (path: string) =>
  `${import.meta.env.BASE_URL}${path.replace(/^\//, "")}`

/**
 * The M3E theme this page runs.
 *
 * `variant: "sharea"` is the brand scheme generated by `npm run colors:report`
 * from the brand navy, with the gold as the tertiary palette (see
 * docs/color-mapping.md). The seed below is only what the M3E color picker would
 * start from if one were ever added — the scheme itself is static, so the page
 * paints the documented hexes immediately.
 */
export const THEME_SEED = "#0F2A4A"

export const M3E_THEME = {
  source: { primary: THEME_SEED },
  variant: "sharea",
  /** light/dark values are generated together; the page keeps dark */
  contrast: "standard",
  spec: "2021",
  /** M3E's own motion scheme; page-level motion is hand-written and minimal */
  motion: "expressive",
  /** 1 = the M3 corner scale */
  shapeScale: 1,
} as const
